metadata.shader:
struct Shape { rows: u32, cols: u32, pairs: u32, parameters: u32, roundingMask: u32 }
@group(0) @binding(0) var<storage, read> a: array<vec2<f32>>;
@group(0) @binding(1) var<storage, read> b: array<vec2<f32>>;
@group(0) @binding(2) var<storage, read> za: array<vec2<f32>>;
@group(0) @binding(3) var<storage, read> zb: array<vec2<f32>>;
@group(0) @binding(4) var<storage, read_write> out: array<vec4<f32>>;
@group(0) @binding(5) var<uniform> shape: Shape;
var<workgroup> tileA: array<vec2<f32>, 256>;
var<workgroup> tileB: array<vec2<f32>, 256>;
@compute @workgroup_size(16, 16)
fn main(@builtin(global_invocation_id) gid: vec3<u32>, @builtin(local_invocation_id) lid: vec3<u32>, @builtin(workgroup_id) group: vec3<u32>) {
  let row = gid.y; let col = gid.x; let t = lid.y * 16u + lid.x;
  let begin = group.z * 1024u;
  var hi = 0.0; var lo = 0.0;
  for (var offset = begin; offset < min(begin + 1024u, shape.pairs); offset += 16u) {
    tileA[t] = vec2<f32>(0.0); tileB[t] = vec2<f32>(0.0);
    if (row < shape.rows && offset + lid.x < shape.pairs) { tileA[t] = a[row * shape.pairs + offset + lid.x]; }
    let bRow = group.x * 16u + lid.y;
    if (bRow < shape.cols && offset + lid.x < shape.pairs) { tileB[t] = b[bRow * shape.pairs + offset + lid.x]; }
    workgroupBarrier();
    for (var k = 0u; k < 16u; k++) {
      let av = tileA[lid.y * 16u + k]; let bv = tileB[lid.x * 16u + k];
      let product = fpMul(av.x, bv.x);
      let residual = fpAdd(fpAdd(fpAdd(productError(av.x, bv.x, product), fpMul(av.x, bv.y)), fpMul(av.y, bv.x)), fpMul(av.y, bv.y));
      let next = fpAdd(hi, product);
      if (abs(hi) >= abs(product)) { lo = fpAdd(lo, fpAdd(fpSub(hi, next), product)); }
      else { lo = fpAdd(lo, fpAdd(fpSub(product, next), hi)); }
      lo = fpAdd(lo, residual);
      hi = next;
    }
    workgroupBarrier();
  }
  let aHi = hi; let aLo = lo; hi = 0.0; lo = 0.0;
  for (var offset = begin; offset < min(begin + 1024u, shape.parameters); offset += 16u) {
    tileA[t] = vec2<f32>(0.0); tileB[t] = vec2<f32>(0.0);
    if (row < shape.rows && offset + lid.x < shape.parameters) { tileA[t] = za[row * shape.parameters + offset + lid.x]; }
    let bRow = group.x * 16u + lid.y;
    if (bRow < shape.cols && offset + lid.x < shape.parameters) { tileB[t] = zb[bRow * shape.parameters + offset + lid.x]; }
    workgroupBarrier();
    for (var k = 0u; k < 16u; k++) {
      let av = tileA[lid.y * 16u + k]; let bv = tileB[lid.x * 16u + k];
      let product = fpMul(av.x, bv.x);
      let residual = fpAdd(fpAdd(fpAdd(productError(av.x, bv.x, product), fpMul(av.x, bv.y)), fpMul(av.y, bv.x)), fpMul(av.y, bv.y));
      let next = fpAdd(hi, product);
      if (abs(hi) >= abs(product)) { lo = fpAdd(lo, fpAdd(fpSub(hi, next), product)); }
      else { lo = fpAdd(lo, fpAdd(fpSub(product, next), hi)); }
      lo = fpAdd(lo, residual);
      hi = next;
    }
    workgroupBarrier();
  }
  let chunks = (max(shape.pairs, shape.parameters) + 1023u) / 1024u;
  if (row < shape.rows && col < shape.cols) { out[(row * shape.cols + col) * chunks + group.z] = vec4<f32>(aHi, aLo, hi, lo); }
}
fn rounded(value: f32) -> f32 {
  return bitcast<f32>(bitcast<u32>(value) ^ shape.roundingMask);
}
fn fpAdd(a: f32, b: f32) -> f32 { return rounded(a + b); }
fn fpSub(a: f32, b: f32) -> f32 { return rounded(a - b); }
fn fpMul(a: f32, b: f32) -> f32 { return rounded(a * b); }
fn productError(a: f32, b: f32, product: f32) -> f32 {
  // Split each 24-bit significand into two <=12-bit pieces. Every component
  // product is representable in f32 in the normal range. Unlike fma(), these
  // error-recovery operations do not depend on optional fused evaluation.
  let ah = bitcast<f32>(bitcast<u32>(a) & 0xfffff000u);
  let bh = bitcast<f32>(bitcast<u32>(b) & 0xfffff000u);
  let al = fpSub(a, ah); let bl = fpSub(b, bh);
  let first = fpSub(fpMul(ah, bh), product);
  return fpAdd(fpAdd(fpAdd(first, fpMul(ah, bl)), fpMul(al, bh)), fpMul(al, bl));
}

